from Bindings import Bindings
from runtime.base import LanguageError

# Environment-related classes
#
# envRef is envVal with one level of indirection: a Binding holds a Ref
# rather than a Val, so a binding's value can be mutated in place by
# `set`. applyEnvRef is the primitive; applyEnv is derived from it.
#
# checkDuplicates returns None. That is the majority shape across the
# seven languages that use envRef, and no caller anywhere in src/ uses a
# return value from it. Do not restore the Set-returning variant that the
# old flat src/Env/envRef and src/REF/envRef carried.


class Env:

    @staticmethod
    def checkDuplicates(symbolList, msg=""):
        seen = set()
        for sym in symbolList:
            s = sym.lexeme
            if s in seen:
                raise LanguageError("duplicate ID " + s + msg)
            seen.add(s)

    @staticmethod
    def initEnv():
        from EnvNode import EnvNode
        from EnvNull import EnvNull
        return EnvNode(Bindings(), EnvNull())

    def lookup(self, sym):
        raise NotImplementedError

    def applyEnvRef(self, sym):
        raise NotImplementedError

    def applyEnv(self, sym):
        return self.applyEnvRef(sym).deRef()

    def extendEnvRef(self, bindings):
        from EnvNode import EnvNode
        return EnvNode(bindings, self)

    def add(self, binding):
        raise NotImplementedError

from Env import Env


class EnvNode(Env):

    def __init__(self, bindings, env):
        self.bindings = bindings
        self.env = env

    def lookup(self, sym):
        return self.bindings.lookup(sym)

    def applyEnvRef(self, sym):
        b = self.bindings.lookup(sym)
        if b is None:
            return self.env.applyEnvRef(sym)
        return b.ref

    def add(self, binding):
        self.bindings.add(binding)
        return self

    def __str__(self):
        return f"{self.bindings}----\n{self.env}"

from Env import Env
from runtime.base import LanguageError


class EnvNull(Env):

    def applyEnvRef(self, sym):
        raise LanguageError("no binding for " + sym)

    def lookup(self, sym):
        return None

    def add(self, binding):
        raise LanguageError("no bindings to add to")

    def __str__(self):
        return "\n"

class Binding:

    def __init__(self, id, ref):
        self.id = id
        self.ref = ref

    def __str__(self):
        return f"[{self.id}:{self.ref.deRef()}]"

from Binding import Binding
from runtime.base import LanguageError


class Bindings:

    def __init__(self, idList=None, refList=None):
        self.bindingList = []
        if idList is not None:
            if refList is None or len(idList) != len(refList):
                raise LanguageError("list sizes mismatch")
            for sym, r in zip(idList, refList):
                self.bindingList.append(Binding(sym.lexeme, r))

    def lookup(self, sym):
        for b in self.bindingList:
            if sym == b.id:
                return b
        return None

    def add(self, binding):
        self.bindingList.append(binding)

    def size(self):
        return len(self.bindingList)

    def __str__(self):
        s = ""
        for b in self.bindingList:
            s += f"{b}\n"
        return s

from runtime.base import LanguageError


class Val:

    # Some Vals can be applied to a list of arguments (e.g. a ProcVal).
    # Like the evaluation of an expression, the application of a Val takes
    # place in the context of an environment, which arrives as the second
    # parameter. An applied Val may use or ignore that environment as its
    # own semantics require.
    def apply(self, args, env):
        raise LanguageError(f"Cannot apply {self}")

    def isTrue(self):
        return True

    def intVal(self):
        raise LanguageError(f"{self}: not an Int")

from Val import Val


class IntVal(Val):

    def __init__(self, val):
        self.val = int(val)

    def intVal(self):
        return self

    def __str__(self):
        return str(self.val)

    def isTrue(self):
        return self.val != 0

class Ref:

    @staticmethod
    def valsToRefs(valList):
        from ValRef import ValRef
        return [ValRef(v) for v in valList]

    def deRef(self):
        raise NotImplementedError

    def setRef(self, v):
        raise NotImplementedError

    def copyOut(self):
        pass

from Ref import Ref


class ValRef(Ref):

    def __init__(self, val):
        self.val = val

    def deRef(self):
        return self.val

    def setRef(self, v):
        self.val = v
        return v

    def __str__(self):
        return str(self.val)

from ValRef import ValRef


class VarRef(ValRef):

    def __init__(self, ref):
        super().__init__(ref.deRef())   # copy in: a new ref holding a copy
        self.ref = ref                  # the variable's own ref, kept for later

    def copyOut(self):
        # Put this ref's value back into the variable's own ref.
        self.ref.setRef(self.deRef())

from Bindings import Bindings
from Val import Val
from runtime.base import LanguageError


class ProcVal(Val):

    def __init__(self, formals, body, env):
        self.formals = formals
        self.body = body
        self.env = env

    def apply(self, args, env):
        if len(self.formals.symbolList) != len(args):
            raise LanguageError("formals/args number mismatch")
        bindings = Bindings(self.formals.symbolList, args)
        nenv = self.env.extendEnvRef(bindings)
        result = self.body.eval(nenv)

        for ref in args: 
            ref.copyOut()

        return result

    def __str__(self):
        return "proc"

def eval(self, env):
    return IntVal(self.lit.lexeme)

def __str__(self):
    return self.lit.lexeme

def eval(self, env):
    return env.applyEnv(self.symbol.lexeme)

def evalRef(self, env):
    return VarRef(env.applyEnvRef(self.symbol.lexeme))

def __str__(self):
    return self.symbol.lexeme

def eval(self, env):
    if self.testExp.eval(env).isTrue():
        return self.trueExp.eval(env)
    else:
        return self.falseExp.eval(env)

def __str__(self):
    return f"if {self.testExp} then {self.trueExp} else {self.falseExp}"

def eval(self, env):
    args = self.rands.evalRands(env)
    return self.prim.apply(args)

def __str__(self):
    return f"{self.prim}({self.rands})"

def eval(self, env):
    nenv = self.letDecls.addBindings(env)
    return self.exp.eval(nenv)

def __str__(self):
    return " ...LetExp... "

def eval(self, env):
    env = self.letDecls.addLetrecBindings(env)
    return self.exp.eval(env)

def __str__(self):
    return " ...LetrecExp... "

def addBindings(self, env):
    valList = [e.eval(env) for e in self.expList]
    refList = Ref.valsToRefs(valList)
    bindings = Bindings(self.symbolList, refList)
    return env.extendEnvRef(bindings)

def addLetrecBindings(self, env):
    env = env.extendEnvRef(Bindings())
    for sym, e in zip(self.symbolList, self.expList):
        val = e.eval(env)
        env.add(Binding(sym.lexeme, ValRef(val)))
    return env

def __str__(self):
    return " ...LetDecls... "

def eval(self, env):
    return self.proc.makeClosure(env)

def __str__(self):
    return " ...ProcExp... "

def eval(self, env):
    v = self.exp.eval(env)
    args = self.rands.evalRandsRef(env)
    return v.apply(args, env)

def __str__(self):
    return " ...AppExp... "

def eval(self, env):
    v = self.exp.eval(env)
    for e in self.seqExps.expList:
        v = e.eval(env)
    return v

def __str__(self):
    return " ...SeqExp... "

def eval(self, env):
    v = self.exp.eval(env)
    ref = env.applyEnvRef(self.symbol.lexeme)
    return ref.setRef(v)

def __str__(self):
    return " ...SetExp... "

def evalRands(self, env):
    return [e.eval(env) for e in self.expList]

def evalRandsRef(self, env):
    return [e.evalRef(env) for e in self.expList]

def __str__(self):
    return ",".join(str(e) for e in self.expList)

def __str__(self):
    return "+"

def apply(self, args):
    if len(args) != 2:
        raise LanguageError("two arguments expected")
    i0 = args[0].intVal().val
    i1 = args[1].intVal().val
    return IntVal(i0 + i1)

def __str__(self):
    return "-"

def apply(self, args):
    if len(args) != 2:
        raise LanguageError("two arguments expected")
    i0 = args[0].intVal().val
    i1 = args[1].intVal().val
    return IntVal(i0 - i1)

def __str__(self):
    return "*"

def apply(self, args):
    if len(args) != 2:
        raise LanguageError("two arguments expected")
    i0 = args[0].intVal().val
    i1 = args[1].intVal().val
    return IntVal(i0 * i1)

def __str__(self):
    return "/"

def apply(self, args):
    if len(args) != 2:
        raise LanguageError("two arguments expected")
    i0 = args[0].intVal().val
    i1 = args[1].intVal().val
    if i1 == 0:
        raise LanguageError("attempt to divide by zero")
    return IntVal(int(i0 / i1))

def __str__(self):
    return "add1"

def apply(self, args):
    if len(args) != 1:
        raise LanguageError("one argument expected")
    i0 = args[0].intVal().val
    return IntVal(i0 + 1)

def __str__(self):
    return "sub1"

def apply(self, args):
    if len(args) != 1:
        raise LanguageError("one argument expected")
    i0 = args[0].intVal().val
    return IntVal(i0 - 1)

def __str__(self):
    return "zero?"

def apply(self, args):
    if len(args) != 1:
        raise LanguageError("one argument expected")
    i0 = args[0].intVal().val
    return IntVal(1 if i0 == 0 else 0)
